// NOVEL (hand-authored) — not generated by CLI Printing Press.
// Recorded in .printing-press-patches/garmin-windowed-sync.json.
//
// Garmin's daily-statistics endpoints cap one request at 28 calendar days
// (verified live 2026-09-07: /usersummary-service/stats/steps/daily over 364
// days returns HTTP 400, over 28 days returns 200 with 28 rows), so a deep
// archive is walked one window at a time. That walk needs two things the
// generated store does not provide:
//
//  1. Per-series calendar state — the filled range: the oldest day the
//     series has been filled from and the newest day it is complete through.
//     It lives in its own table rather than in the generated sync_state so a
//     future press regeneration, or the generated `sync --full` cursor clear,
//     cannot wipe an earliest_day that costs a multi-year re-walk to rebuild.
//     Each series' progress is ALSO mirrored into the generated sync_state so
//     generated readers (doctor, tail, incremental watermarks) still see it.
//
//  2. Caller-supplied row ids. The generated UpsertBatchDetailed derives an id
//     from the payload; Garmin's daily rows are keyed by "calendarDate" and its
//     hrTimeInZones payload is a bare array with no id at all. UpsertKeyedBatch
//     takes the id from the caller and otherwise follows the generated write
//     path exactly (merge-preserving generic row, FTS, typed-table projection
//     under a savepoint).
package store

import (
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"time"
)

// GarminSeriesState is the windowed-sync bookmark for one series.
//
// Days are calendar dates in YYYY-MM-DD form, in the account's local calendar
// as Garmin reports it — not timestamps. An empty string means "not known yet".
type GarminSeriesState struct {
	// Series is the series name; it matches the resource_type the series
	// writes and the sync_state row it mirrors into.
	Series string
	// LastCompleteDay is the newest day whose data is known complete. Today
	// is never recorded here: the day is still accruing.
	LastCompleteDay string
	// EarliestDay is the oldest day this series has been FILLED FROM: every
	// day from here through LastCompleteDay has been requested. It is not a
	// claim that a row exists for that day — a series is sparse by nature —
	// only that the range was asked for and will not be asked for again.
	EarliestDay string
	// FrontierDay is legacy state written by the retired backward walk. The
	// column stays so an existing archive still loads; nothing reads it.
	FrontierDay string
	// StopReason records why the last run of this series stopped early:
	// "all_windows_refused" (every window this run asked for came back
	// HTTP 403), "interrupted", "feed_exhausted" (the activity feed reached
	// its end), or "" for a run that finished normally. Rows written before
	// walk version 2 may still carry the retired backward walk's reasons.
	StopReason string
	// EmptyWindows is legacy state written by the retired backward walk. The
	// column stays so an existing archive still loads; nothing reads it.
	EmptyWindows int
	// TotalRows is how many rows this series holds, recounted from the
	// archive at the end of every series run rather than accumulated: the
	// walk re-requests the feed's boundary day and a refresh window of days
	// every run, so a running total would count the same row once per run.
	TotalRows int
	// WalkVersion is the walk that wrote this row. Rows below
	// GarminWalkVersion were written by the retired backward walk, whose
	// bookmark meant something different, and are read as unfilled.
	WalkVersion int
	UpdatedAt   time.Time
}

// GarminWalkVersion is the current walk's state version. A state row carrying
// a lower number was written by the retired backward walk — whose
// last_complete_day was the top of a range walked from the newest day down,
// not the top of a contiguous filled range — so it cannot be resumed from and
// is read as unfilled. Rows are rewritten at this version on the first save.
const GarminWalkVersion = 2

// KeyedRow is one row to store with an id the caller chose.
type KeyedRow struct {
	ID   string
	Data json.RawMessage
}

const garminSeriesStateDDL = `CREATE TABLE IF NOT EXISTS garmin_series_state (
	series TEXT PRIMARY KEY,
	last_complete_day TEXT NOT NULL DEFAULT '',
	earliest_day TEXT NOT NULL DEFAULT '',
	frontier_day TEXT NOT NULL DEFAULT '',
	stop_reason TEXT NOT NULL DEFAULT '',
	empty_windows INTEGER NOT NULL DEFAULT 0,
	total_rows INTEGER NOT NULL DEFAULT 0,
	walk_version INTEGER NOT NULL DEFAULT 0,
	updated_at DATETIME
)`

// EnsureGarminSeriesState creates the windowed-sync state table if it is
// absent. It is idempotent and safe to call on every invocation.
func (s *Store) EnsureGarminSeriesState() error {
	s.lockForWrite()
	defer s.unlockAfterWrite()
	if _, err := s.db.Exec(garminSeriesStateDDL); err != nil {
		return fmt.Errorf("creating garmin_series_state: %w", err)
	}
	// walk_version was added after the first archives were written, so the
	// table may already exist without it. ALTER TABLE ADD COLUMN is the only
	// migration needed — the default 0 is exactly "written by a walk older
	// than GarminWalkVersion", which is what an existing row is.
	has, err := s.garminSeriesStateHasColumn("walk_version")
	if err != nil {
		return err
	}
	if !has {
		if _, err := s.db.Exec(`ALTER TABLE garmin_series_state ADD COLUMN walk_version INTEGER NOT NULL DEFAULT 0`); err != nil {
			return fmt.Errorf("adding garmin_series_state.walk_version: %w", err)
		}
	}
	return nil
}

func (s *Store) garminSeriesStateHasColumn(name string) (bool, error) {
	rows, err := s.db.Query(`PRAGMA table_info(garmin_series_state)`)
	if err != nil {
		return false, fmt.Errorf("reading garmin_series_state columns: %w", err)
	}
	defer rows.Close()
	for rows.Next() {
		var (
			cid        int
			colName    string
			colType    string
			notNull    int
			defaultVal sql.NullString
			pk         int
		)
		if err := rows.Scan(&cid, &colName, &colType, &notNull, &defaultVal, &pk); err != nil {
			return false, err
		}
		if colName == name {
			return true, rows.Err()
		}
	}
	return false, rows.Err()
}

// GetGarminSeriesState returns the bookmark for one series. A series that has
// never run returns a zero-valued state with its Series field set and a nil
// error, so callers do not have to distinguish absence from failure.
func (s *Store) GetGarminSeriesState(series string) (GarminSeriesState, error) {
	st := GarminSeriesState{Series: series}
	var updated sql.NullString
	err := s.db.QueryRow(
		`SELECT last_complete_day, earliest_day, frontier_day, stop_reason, empty_windows, total_rows, walk_version, updated_at
		   FROM garmin_series_state WHERE series = ?`, series,
	).Scan(&st.LastCompleteDay, &st.EarliestDay, &st.FrontierDay, &st.StopReason, &st.EmptyWindows, &st.TotalRows, &st.WalkVersion, &updated)
	if errors.Is(err, sql.ErrNoRows) {
		return st, nil
	}
	if err != nil {
		return st, err
	}
	if updated.Valid {
		if ts, parseErr := time.Parse(time.RFC3339, updated.String); parseErr == nil {
			st.UpdatedAt = ts
		}
	}
	return st, nil
}

// SaveGarminSeriesState writes one series' bookmark. UpdatedAt is stamped
// here so every caller records the same clock, and so is WalkVersion: a row
// this walk writes is by definition a row this walk can resume from, so the
// version is not something a caller can forget to set.
func (s *Store) SaveGarminSeriesState(st GarminSeriesState) error {
	if st.Series == "" {
		return errors.New("garmin series state requires a series name")
	}
	s.lockForWrite()
	defer s.unlockAfterWrite()
	_, err := s.db.Exec(
		`INSERT INTO garmin_series_state
		   (series, last_complete_day, earliest_day, frontier_day, stop_reason, empty_windows, total_rows, walk_version, updated_at)
		 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
		 ON CONFLICT(series) DO UPDATE SET
		   last_complete_day = excluded.last_complete_day,
		   earliest_day      = excluded.earliest_day,
		   frontier_day      = excluded.frontier_day,
		   stop_reason       = excluded.stop_reason,
		   empty_windows     = excluded.empty_windows,
		   total_rows        = excluded.total_rows,
		   walk_version      = excluded.walk_version,
		   updated_at        = excluded.updated_at`,
		st.Series, st.LastCompleteDay, st.EarliestDay, st.FrontierDay, st.StopReason,
		st.EmptyWindows, st.TotalRows, GarminWalkVersion, time.Now().UTC().Format(time.RFC3339),
	)
	if err != nil {
		return fmt.Errorf("saving garmin series state for %s: %w", st.Series, err)
	}
	return nil
}

// ListGarminSeriesState returns every series bookmark, oldest series name
// first, for status reporting.
func (s *Store) ListGarminSeriesState() ([]GarminSeriesState, error) {
	rows, err := s.db.Query(
		`SELECT series, last_complete_day, earliest_day, frontier_day, stop_reason, empty_windows, total_rows, walk_version, updated_at
		   FROM garmin_series_state ORDER BY series`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []GarminSeriesState
	for rows.Next() {
		var st GarminSeriesState
		var updated sql.NullString
		if err := rows.Scan(&st.Series, &st.LastCompleteDay, &st.EarliestDay, &st.FrontierDay,
			&st.StopReason, &st.EmptyWindows, &st.TotalRows, &st.WalkVersion, &updated); err != nil {
			return nil, err
		}
		if updated.Valid {
			if ts, parseErr := time.Parse(time.RFC3339, updated.String); parseErr == nil {
				st.UpdatedAt = ts
			}
		}
		out = append(out, st)
	}
	return out, rows.Err()
}

// UpsertKeyedBatch stores rows under caller-supplied ids in one transaction.
//
// It mirrors UpsertBatchDetailed's write path — merge-preserving generic row,
// FTS index, typed-table projection guarded by a per-row savepoint — and
// differs only in taking the id from the caller instead of extracting it from
// the payload. A row whose id is empty is skipped rather than stored under a
// blank key; the skipped count is returned so a caller can report it honestly.
func (s *Store) UpsertKeyedBatch(resourceType string, rows []KeyedRow) (stored int, skipped int, err error) {
	if len(rows) == 0 {
		return 0, 0, nil
	}
	s.lockForWrite()
	defer s.unlockAfterWrite()
	tx, err := s.db.Begin()
	if err != nil {
		return 0, 0, fmt.Errorf("starting keyed batch transaction: %w", err)
	}
	defer tx.Rollback() //nolint:errcheck // rollback after a successful commit is a no-op

	for i, row := range rows {
		if row.ID == "" || len(row.Data) == 0 {
			skipped++
			continue
		}
		obj, decodeErr := DecodeJSONObject(row.Data)
		if decodeErr != nil {
			skipped++
			continue
		}
		storageID := resourceStorageID(resourceType, row.ID, obj)
		item := s.mergeIncomingResourceData(tx, resourceType, storageID, row.Data)
		if merged, mergeErr := DecodeJSONObject(item); mergeErr == nil {
			obj = merged
		}
		if err := s.upsertGenericResourceTx(tx, resourceType, storageID, item); err != nil {
			return stored, skipped, fmt.Errorf("upserting %s/%s: %w", resourceType, storageID, err)
		}
		stored++

		deriveScopeColumns(obj)

		savepoint := fmt.Sprintf("pp_garmin_typed_%d", i)
		if _, err := tx.Exec("SAVEPOINT " + savepoint); err != nil {
			return stored, skipped, fmt.Errorf("savepoint begin for %s/%s: %w", resourceType, storageID, err)
		}
		var typedErr error
		switch resourceType {
		case "account":
			typedErr = s.upsertAccountTx(tx, storageID, obj, item)
		case "activities":
			typedErr = s.upsertActivitiesTx(tx, storageID, obj, item)
		case "sleep":
			typedErr = s.upsertSleepTx(tx, storageID, obj, item)
		case "steps":
			typedErr = s.upsertStepsTx(tx, storageID, obj, item)
		case "training":
			typedErr = s.upsertTrainingTx(tx, storageID, obj, item)
		case "wellness":
			typedErr = s.upsertWellnessTx(tx, storageID, obj, item)
		}
		if typedErr != nil {
			// The generic row is the archive; the typed projection is a
			// convenience index. Roll back only the projection so one
			// unexpected field shape cannot cost the whole window.
			if _, rbErr := tx.Exec("ROLLBACK TO SAVEPOINT " + savepoint); rbErr != nil {
				return stored, skipped, fmt.Errorf("rollback to savepoint for %s/%s (typed err: %v): %w", resourceType, storageID, typedErr, rbErr)
			}
		}
		if _, err := tx.Exec("RELEASE SAVEPOINT " + savepoint); err != nil {
			return stored, skipped, fmt.Errorf("release savepoint for %s/%s: %w", resourceType, storageID, err)
		}
	}

	if err := tx.Commit(); err != nil {
		return 0, skipped, err
	}
	return stored, skipped, nil
}

// CountResourceRows returns how many rows one resource type holds.
func (s *Store) CountResourceRows(resourceType string) (int, error) {
	var n int
	err := s.db.QueryRow(`SELECT COUNT(*) FROM resources WHERE resource_type = ?`, resourceType).Scan(&n)
	return n, err
}

// MissingResourceIDs returns the subset of ids that resourceType does not
// already hold. It is how a per-parent fan-out (hrTimeInZones per activity)
// finds the work still outstanding without re-fetching what is stored.
func (s *Store) MissingResourceIDs(resourceType string, ids []string) ([]string, error) {
	if len(ids) == 0 {
		return nil, nil
	}
	have := make(map[string]bool, len(ids))
	rows, err := s.db.Query(`SELECT id FROM resources WHERE resource_type = ?`, resourceType)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		have[BareResourceID(id)] = true
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	missing := make([]string, 0, len(ids))
	for _, id := range ids {
		if !have[id] {
			missing = append(missing, id)
		}
	}
	return missing, nil
}

// ResourceIDsNewestFirst returns stored ids for one resource type, newest
// synced first, capped by limit (0 = no cap).
func (s *Store) ResourceIDsNewestFirst(resourceType string, limit int) ([]string, error) {
	query := `SELECT id FROM resources WHERE resource_type = ? ORDER BY updated_at DESC, id DESC`
	args := []any{resourceType}
	if limit > 0 {
		query += ` LIMIT ?`
		args = append(args, limit)
	}
	rows, err := s.db.Query(query, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []string
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		out = append(out, BareResourceID(id))
	}
	return out, rows.Err()
}

// DistinctResourceIDs returns every distinct bare id held by any of the named
// resource types, sorted. The day-keyed series store one row per calendar day
// under the day as its id, so this is how the walk reads "which days does the
// archive already have a reading for" without loading a single payload.
func (s *Store) DistinctResourceIDs(resourceTypes []string) ([]string, error) {
	if len(resourceTypes) == 0 {
		return nil, nil
	}
	placeholders := make([]string, 0, len(resourceTypes))
	args := make([]any, 0, len(resourceTypes))
	for _, t := range resourceTypes {
		placeholders = append(placeholders, "?")
		args = append(args, t)
	}
	// #nosec G202 -- the only interpolated text is a comma-joined run of
	// literal "?" placeholders built above; every resource type is bound as
	// an argument and none of them reaches the SQL text.
	query := `SELECT DISTINCT id FROM resources WHERE resource_type IN (` +
		strings.Join(placeholders, ",") + `) ORDER BY id`
	rows, err := s.db.Query(query, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []string
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		out = append(out, BareResourceID(id))
	}
	return out, rows.Err()
}

// ResourceJSONFieldValues returns one top-level JSON field of every row of a
// resource type. It exists so a caller can derive a calendar day from the same
// payload field its extractor reads, rather than from a second field that
// could drift away from it.
func (s *Store) ResourceJSONFieldValues(resourceType, field string) ([]string, error) {
	rows, err := s.db.Query(
		`SELECT json_extract(data, '$.' || ?) FROM resources WHERE resource_type = ?`, field, resourceType)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []string
	for rows.Next() {
		var v sql.NullString
		if err := rows.Scan(&v); err != nil {
			return nil, err
		}
		if v.Valid && v.String != "" {
			out = append(out, v.String)
		}
	}
	return out, rows.Err()
}

// ResourceIDJSONFieldValues returns the same field as ResourceJSONFieldValues,
// keyed by the row's bare id. A fan-out asks it "which day did each stored
// parent start on", so a run bounded by a date can decide per parent without
// loading a single payload, and it reads the same field the parent's own
// extractor reads rather than a second one that could drift away from it.
func (s *Store) ResourceIDJSONFieldValues(resourceType, field string) (map[string]string, error) {
	rows, err := s.db.Query(
		`SELECT id, json_extract(data, '$.' || ?) FROM resources WHERE resource_type = ?`, field, resourceType)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := map[string]string{}
	for rows.Next() {
		var id string
		var v sql.NullString
		if err := rows.Scan(&id, &v); err != nil {
			return nil, err
		}
		if v.Valid && v.String != "" {
			out[BareResourceID(id)] = v.String
		}
	}
	return out, rows.Err()
}

// AverageResourceBytes returns the mean stored size of one resource type's
// rows and how many rows that mean is over. A caller estimating what a fetch
// will cost uses it to replace a hand-measured constant with this archive's
// own numbers once there are enough rows for the mean to mean anything.
func (s *Store) AverageResourceBytes(resourceType string) (avg int, rows int, err error) {
	var avgNull sql.NullFloat64
	err = s.db.QueryRow(
		`SELECT COUNT(*), AVG(LENGTH(data)) FROM resources WHERE resource_type = ?`, resourceType,
	).Scan(&rows, &avgNull)
	if err != nil {
		return 0, 0, err
	}
	if avgNull.Valid {
		avg = int(avgNull.Float64)
	}
	return avg, rows, nil
}
